// each .analyze("…") lights up its instrument in the Stage visual
setcpm(128/4)

const SECTIONS = [['Crescendo', 17], ['Crescendo 2', 25], ['Intro', 8], ['Drop', 16], ['Outro', 4]]
const TEMPO = {'Crescendo': 128, 'Crescendo 2': 128, 'Intro': 128, 'Drop': 128, 'Outro': 128}

// section lanes: 1 plays, 0 is silent, values in between fade
const section1 = "<1!17 0!53>"  // Crescendo · 17 bars · 128 BPM · E · Em
const section2 = "<0!17 1!25 0!28>"  // Crescendo 2 · 25 bars · 128 BPM · E · Em F Em D
const section3 = "<0!42 1!8 0.5 0!19>"  // Intro · 8 bars · 128 BPM · E · Em Em Em F
const section4 = "<0!50 0.5 1!15 0!4>"  // Drop · 16 bars · 128 BPM · E · Em F Em D · fades in over 1 bars
const section5 = "<0!66 1!4>"  // Outro · 4 bars · 128 BPM · E · Em

// ========== drums ==========
// Crescendo · bars 1-17 · pattern drop~1
// Drums · RolandTR909
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.9).distort(1.2).distortvol(.5).mask(section1).velocity(section1).orbit(1).analyze("kick")
